{
  "artifact_type": "plan@1",
  "id": "PLAN-TRACK4-RELEASE-PIPELINE-CONTRACT-CORRECTNESS",
  "spec_file_path": ".claude/specs/SPEC-TRACK4-RELEASE-PIPELINE-CONTRACT-CORRECTNESS.json",
  "spec_hash": "sha256:26502a95f78494d2c1759752e86543a70d0a22588ef4dbec18f2324752e52255",
  "linked_requirement": "REQ-TRACK4-RELEASE-PIPELINE-CONTRACT-CORRECTNESS",
  "reasoning": "Verified every api_surface claim against live code before writing tasks (all citations held: action.yml lines 90-97 have exactly the described exit-0-true/exit-2-false/else-passthrough bug with no exit-1 branch at all; main.rs:19-21 wrongly claims 0 under --check with pending changesets; tag.rs:82-117/53-80 unconditionally push release.sha; publish.rs:427 hardcodes None; DiagnosticCode::ChangelogSectionNotFound exists unemitted at diagnostic.rs:144, ChangelogReadError does not exist yet; ReleaseEntry.changelog_section already has skip_serializing_if at plan.rs:116-117; Package.changelog is workspace-root-relative, always Some, set at walk.rs:323/387-392). Four disjoint clusters, sequenced arbitrarily since none depend on each other, but each cluster's internal tasks are ordered (foundation before use, e.g. the new DiagnosticCode variant before the code that emits it). Two tasks (T5, T8/T9) are pure regression-proof tasks whose assertions pass immediately because the single cohesive fix in the preceding task already satisfies them -- documented explicitly per task rather than forcing an artificial red phase that would require temporarily breaking working code. Stub CommandRunner fixtures for tag.rs (T3/T4) follow the exact pattern of FakeRevParseRunner in aggregate.rs and CountingTagListRunner in tags_laziness_test.rs: a non-git-discoverable tempdir forces GitAccess through the CommandRunner shell fallback deterministically, and TagIndex::build's contains_tag check is satisfied by stubbing `git tag --list` while resolve_commit's three outcomes (Some/None/Err) are satisfied by stubbing `git rev-parse --verify --quiet <tag>^{commit}`. AC-07/AC-08 regression (T5) instead uses a real git repo, since those scenarios exercise the actual tag-creation write path and native gix idempotent-read path that a stub would have to reimplement pointlessly. The AC-13 schema guard (T10) uses field/variant sets captured directly from the live, unmodified binary via `callisto schema --type <X>` before any code in this plan was written, so the expected sets are the true pre-fix baseline, not a guess.",
  "tasks": [
    {
      "task_id": "T1",
      "cluster": "action-script-exit-code",
      "description": "Fix action.yml's 'Inspecting Workspace Status' step so exit 1 -> HAS_CHANGESETS=true, exit 2 -> HAS_CHANGESETS=false, and any other exit code (including 0) fails the step with an ::error:: annotation and a guaranteed non-zero exit, never a passthrough of $STATUS_EXIT.",
      "covers_criteria": ["AC-01", "AC-02", "AC-04"],
      "files": [".github/actions/callisto-action/action.yml", ".github/actions/callisto-action/tests/test_status_check_branching.sh"],
      "reasoning": "Current code (action.yml:90-97) has no branch for exit 1 at all -- exit 0 is wrongly mapped to HAS_CHANGESETS=true, and the else branch does `exit $STATUS_EXIT` which is a passthrough that could itself be 0. Composite-action bash isn't unit-testable via cargo, so this task adds a small, self-contained bash test that extracts the exact run-body text between the step's `::group::1. Inspecting Workspace Status` and its matching `::endgroup::` markers straight out of action.yml (so the test can never drift from the real file) and executes it with a stubbed `callisto` shell function standing in for the binary, for exit codes 1, 2, 0, and 127.",
      "test": {
        "action": "create",
        "file_path": ".github/actions/callisto-action/tests/test_status_check_branching.sh",
        "content": "#!/usr/bin/env bash
# Regression test for the "Inspecting Workspace Status" step's exit-code
# branching in action.yml (AC-01, AC-02, AC-04). Extracts the exact run-body
# text between the step's ::group::1. Inspecting Workspace Status marker and
# its matching ::endgroup:: marker directly out of action.yml, so this test
# always exercises the file's current real logic -- it cannot drift from it.
set -u
ACTION_YML="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)/action.yml"

extract_snippet() {
  sed -n '/::group::1\. Inspecting Workspace Status/,/::endgroup::/p' "$ACTION_YML" | sed '1d;$d'
}

run_case() {
  local stub_exit="$1"
  local tmp_script
  tmp_script="$(mktemp)"
  {
    echo "callisto() { exit ${stub_exit}; }"
    extract_snippet
    echo 'echo "__HAS_CHANGESETS=${HAS_CHANGESETS-<unset>}__"'
  } > "$tmp_script"
  bash "$tmp_script"
  local code=$?
  rm -f "$tmp_script"
  return $code
}

fail=0

# AC-01: exit 1 -> HAS_CHANGESETS=true, step must not fail.
out=$(run_case 1); code=$?
